#pragma once#include <macros/IntrusivePtr.h>#include <string>#include <vector>typedef std::vector<std::string> tVectoredString_;struct SNamedParam {  std::string name, value;};typedef std::vector<SNamedParam> tParamsCont_;class IParameterRead : public ref_counted{public:  virtual ~IParameterRead(){}  virtual void SetName( LPCSTR pszName ) = 0;  virtual BOOL ParsingSingleText( LPCSTR pszText, RECTL *rc ) = 0;//TRUE мое, иначе нужен другой разборщик  virtual std::string GetType() const = 0;  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params ) = 0;  virtual int GetExecOrder() = 0;};typedef TIntrusivePtr<IParameterRead> IParameterReadPtr;//////////////////////////////////////////////////////////////////////////class IParamReaderFactory : public ref_counted{public:  virtual ~IParamReaderFactory(){}  virtual IParameterReadPtr CreateReader() = 0;};typedef TIntrusivePtr<IParamReaderFactory> IParamReaderFactoryPtr;